318→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
319→// project directories if needed.
320→func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
321→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
322→	if err != nil {
323→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
324→	}
325→	// Only call PrepareTranscript when the file already exists — it flushes
326→	// in-progress writes, but can't conjure a file that was never started.
327→	// This avoids agents like Cursor polling for 3s on non-existent files
328→	// during auto-detection.
329→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
330→		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
331→			if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
332→				logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
333→			}
334→		}
335→		return transcriptPath, nil
336→	}
337→	found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
338→	if searchErr == nil {
339→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
340→		return found, nil
341→	}
342→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
343→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
344→}
345→
346→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
347→// transcript resolution succeeds for the given session ID.
348→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
349→	for _, name := range agent.List() {
350→		if name == skip {
351→			continue
352→		}
353→		ag, err := agent.Get(name)
354→		if err != nil {
355→			continue
356→		}
357→		path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
358→		if resolveErr != nil {
359→			logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
360→			continue
361→		}
362→		return ag, path, nil
363→	}
364→	return nil, "", errors.New("transcript not found for any registered agent")
365→}
